import os
import json
from urllib.parse import urlencode

import requests


class Auth0FederatedLoginFlow:
    """
    Handles OAuth2/OIDC callback exchange for authorization code -> tokens using Auth0.
    Provider-identifying signals:
      - Auth0 domain hostname
      - Auth0-specific environment variables
    """

    def __init__(self, domain=None, client_id=None, client_secret=None, redirect_uri=None):
        self.domain = (domain or os.getenv("AUTH0_DOMAIN", "")).strip()
        self.client_id = (client_id or os.getenv("AUTH0_CLIENT_ID", "")).strip()
        self.client_secret = (client_secret or os.getenv("AUTH0_CLIENT_SECRET", "")).strip()
        self.redirect_uri = (redirect_uri or os.getenv("AUTH0_REDIRECT_URI", "")).strip()

        if not self.domain:
            raise ValueError("Missing Auth0 domain")
        if not self.client_id:
            raise ValueError("Missing Auth0 client_id")
        if not self.client_secret:
            raise ValueError("Missing Auth0 client_secret")
        if not self.redirect_uri:
            raise ValueError("Missing Auth0 redirect_uri")

    @property
    def token_endpoint(self):
        return f"https://{self.domain}/oauth/token"

    def build_authorize_url(self, scope="openid profile email", state=None, audience=None):
        params = {
            "response_type": "code",
            "client_id": self.client_id,
            "redirect_uri": self.redirect_uri,
            "scope": scope,
        }
        if state is not None:
            params["state"] = state
        if audience is not None:
            params["audience"] = audience
        return f"https://{self.domain}/authorize?{urlencode(params)}"

    def exchange_code_for_tokens(self, code):
        if not code:
            raise ValueError("Missing authorization code")

        payload = {
            "grant_type": "authorization_code",
            "client_id": self.client_id,
            "client_secret": self.client_secret,
            "code": code,
            "redirect_uri": self.redirect_uri,
        }

        headers = {"Content-Type": "application/json"}

        response = requests.post(self.token_endpoint, headers=headers, data=json.dumps(payload), timeout=15)
        response.raise_for_status()

        tokens = response.json()
        normalized = {
            "access_token": tokens.get("access_token"),
            "id_token": tokens.get("id_token"),
            "refresh_token": tokens.get("refresh_token"),
            "token_type": tokens.get("token_type"),
            "expires_in": tokens.get("expires_in"),
            "scope": tokens.get("scope"),
            "raw": tokens,
        }
        return normalized

    def handle_callback(self, query_params):
        """
        Accepts a dict-like object containing the callback query parameters.
        Expected parameters:
          - code: authorization code
          - state: optional state (caller may validate before invoking)
          - error: optional OAuth error
        """
        error = query_params.get("error")
        if error:
            description = query_params.get("error_description", "")
            raise RuntimeError(f"OAuth callback error: {error}. {description}".strip())

        code = query_params.get("code")
        if not code:
            raise ValueError("Callback did not include an authorization code")

        return self.exchange_code_for_tokens(code)


def handle_federated_login_callback(query_params, domain=None, client_id=None, client_secret=None, redirect_uri=None):
    flow = Auth0FederatedLoginFlow(
        domain=domain,
        client_id=client_id,
        client_secret=client_secret,
        redirect_uri=redirect_uri,
    )
    return flow.handle_callback(query_params)
